    description: {
      de: "Ein interaktives Edutainment-Zentrum, in dem Kinder durch Rollenspiele verschiedene Berufe in einer Miniaturstadt ausprobieren können.",
      hu: "Interaktív szórakoztató-oktató központ, ahol a gyerekek szerepjátékokon keresztül próbálhatnak ki különböző szakmákat egy miniatűr városban.",
      ro: "Un centru interactiv de edutainment, unde copiii pot încerca diverse profesii prin jocuri de rol într-un oraș în miniatură.",
      en: "An interactive edutainment center where children can try out various professions through role-play in a miniature city.",
      es: "Un centro de entretenimiento educativo interactivo donde los niños pueden probar diferentes profesiones mediante juegos de rol en una ciudad en miniatura.",
      pt: "Um centro de entretenimento educativo interativo onde as crianças podem experimentar diferentes profissões através de jogos de papéis numa cidade em miniatura.",
      fr: "Un centre ludo-éducatif interactif où les enfants peuvent s'essayer à différentes professions par le biais de jeux de rôle dans une ville miniature.",
    },
