      es: ["Incluye un gran lago artificial.", "Ofrece un anfiteatro para eventos.", "Posee extensos senderos para caminar.", "Cuenta con un centro comercial en el lugar."],
      pt: ["Inclui um grande lago artificial.", "Oferece um anfiteatro para eventos.", "Possui caminhos extensos para caminhadas.", "Dispõe de um centro comercial no local."],
