      es: ["Superficie: 50 km²", "Año de inicio: 1980", "Producción anual de verduras: 50.000 toneladas", "Riego: aguas residuales tratadas", "Productos: tomates, pepinos, trigo", "Administración: Autoridad Pública de Kuwait"],
